hub(c)}>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<Github class=\\\"size-3.5\\\" />\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tView on GitHub\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Item>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t{#if c.canDelete}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t{#if c.url}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Separator />\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Item variant=\\\"destructive\\\" onSelect={() => remove(c)}>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<Trash2 class=\\\"size-3.5\\\" />\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tDelete\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Item>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n \\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Content>\\n \\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Root>\\n \\t\\t\\t\\t\\t\\t{/if}\\n@@ -301,7 +319,7 @@\\n \\t\\talign-items: center;\\n \\t\\tgap: 10px;\\n \\t\\twidth: 100%;\\n-\\t\\tmargin-top: 10px;\\n+\\t\\tmargin-top: 4px;\\n \\t}\\n \\t.reply-avatar {\\n \\t\\tborder-radius: 999px;\\n@@ -334,8 +352,8 @@\\n      resolved (and its comments are dimmed). */\\n \\t.thread-actions {\\n \\t\\tdisplay: flex;\\n-\\t\\tmargin-top: 10px;\\n-\\t\\tpadding-top: 8px;\\n+\\t\\tmargin-top: 6px;\\n+\\t\\tpadding-top: 6px;\\n \\t\\tborder-top: 1px solid var(--color-border);\\n \\t}\\n \\t.resolved-tag {\\n\",\n      \"oldContents\": \"<script lang=\\\"ts\\\">\\n\\timport { Check, Copy, MessageSquare, MoreHorizontal, Trash2 } from 'lucide-svelte';\\n\\timport { Button } from './ui/button';\\n\\timport * as DropdownMenu from './ui/dropdown-menu';\\n\\timport MarkdownComposer from './MarkdownComposer.svelte';\\n\\timport { actions, app, composerKey, effectiveGithubAccount } from '$lib/store.svelte';\\n\\timport { formatRelative } from '$lib/utils';\\n\\timport { renderMarkdown } from '$lib/markdown';\\n\\timport '$lib/markdown.css';\\n\\timport type { PRReviewComment } from '@shared/types';\\n\\n\\t// Metadata stamped onto every DiffLineAnnotation we feed @pierre/diffs.\\n\\t// Lets this single component render either an existing comment row or the\\n\\t// pending composer for a brand-new comment / reply.\\n\\texport type CommentMeta =\\n\\t\\t| { kind: 'comment'; comment: PRReviewComment }\\n\\t\\t| {\\n\\t\\t\\t\\tkind: 'composer';\\n\\t\\t\\t\\tfilePath: string;\\n\\t\\t\\t\\tline: number;\\n\\t\\t\\t\\tside: 'LEFT' | 'RIGHT';\\n\\t\\t\\t\\treplyTo?: number;\\n\\t\\t  };\\n\\n\\tinterface Props {\\n\\t\\tmeta: CommentMeta;\\n\\t}\\n\\n\\tlet { meta }: Props = $props();\\n\\n\\t// Render the comment body as GitHub-Flavored Markdown (sanitized in\\n\\t// markdown.ts) so comments display formatted text, links, and code — matching\\n\\t// how the same markdown reads on GitHub — rather than as a raw string.\\n\\tlet bodyHtml = $state('');\\n\\t$effect(() => {\\n\\t\\tif (meta.kind !== 'comment') {\\n\\t\\t\\tbodyHtml = '';\\n\\t\\t\\treturn;\\n\\t\\t}\\n\\t\\tconst src = meta.comment.body;\\n\\t\\tconst theme = app.theme;\\n\\t\\tif (!src.trim()) {\\n\\t\\t\\tbodyHtml = '';\\n\\t\\t\\treturn;\\n\\t\\t}\\n\\t\\tlet cancelled = false;\\n\\t\\tvoid renderMarkdown(src, theme)\\n\\t\\t\\t.then((h) => {\\n\\t\\t\\t\\tif (!cancelled) bodyHtml = h;\\n\\t\\t\\t})\\n\\t\\t\\t.catch(() => {\\n\\t\\t\\t\\tif (!cancelled) bodyHtml = '';\\n\\t\\t\\t});\\n\\t\\treturn () => {\\n\\t\\t\\tcancelled = true;\\n\\t\\t};\\n\\t});\\n\\n\\tconst composerState = $derived.by(() => {\\n\\t\\tif (meta.kind !== 'composer') return null;\\n\\t\\tconst key = composerKey(meta.filePath, meta.side, meta.line);\\n\\t\\treturn { key, value: app.pendingComposers[key] ?? null };\\n\\t});\\n\\n\\t// All comments in this comment's thread (root + replies), in display order.\\n\\t// GitHub flattens replies so each carries the top-level comment's id in\\n\\t// `inReplyTo`; the root points at itself. We use this to anchor the\\n\\t// resolve/unresolve control to the LAST comment, so it renders once per\\n\\t// thread, below the whole conversation — not on an individual comment.\\n\\tconst threadComments = $derived.by(() => {\\n\\t\\tif (meta.kind !== 'comment') return [];\\n\\t\\tconst c = meta.comment;\\n\\t\\tconst rootId = c.inReplyTo ?? c.id;\\n\\t\\treturn (app.prComments[c.path] ?? []).filter((x) => (x.inReplyTo ?? x.id) === rootId);\\n\\t});\\n\\tconst isThreadTail = $derived(\\n\\t\\tmeta.kind === 'comment' && threadComments[threadComments.length - 1]?.id === meta.comment.id\\n\\t);\\n\\t// A reply (not the thread root) gets a divider above it so stacked comments\\n\\t// in a thread read as distinct entries rather than one run-on block.\\n\\tconst isReply = $derived(meta.kind === 'comment' && !!meta.comment.inReplyTo);\\n\\n\\t// The viewer's avatar for the GitHub-style reply prompt.\\n\\tconst viewerAvatar = $derived(effectiveGithubAccount()?.avatarUrl ?? '');\\n\\n\\t// Inline reply state. Kept local (not in pendingComposers) so the box stays\\n\\t// an input in place — no swap to a separate composer row, no layout shift.\\n\\tlet replyDraft = $state('');\\n\\tlet replySubmitting = $state(false);\\n\\n\\tfunction submit(): void {\\n\\t\\tif (composerState) void actions.submitComposer(composerState.key);\\n\\t}\\n\\n\\tfunction cancel(): void {\\n\\t\\tif (composerState) actions.cancelComposer(composerState.key);\\n\\t}\\n\\n\\t// Post a reply to the thread. Replies all hang off the top-level comment, so\\n\\t// we pass the root's id as `replyTo`.\\n\\tasync function submitReply(): Promise<void> {\\n\\t\\tif (meta.kind !== 'comment') return;\\n\\t\\tconst body = replyDraft.trim();\\n\\t\\tif (!body || replySubmitting) return;\\n\\t\\tconst c = meta.comment;\\n\\t\\tconst root = threadComments[0] ?? c;\\n\\t\\treplySubmitting = true;\\n\\t\\tconst ok = await actions.submitReply(c.path, root.id, body);\\n\\t\\treplySubmitting = false;\\n\\t\\tif (ok) replyDraft = '';\\n\\t}\\n\\n\\tfunction remove(comment: PRReviewComment): void {\\n\\t\\tvoid actions.deleteComment(comment.id, comment.path);\\n\\t}\\n\\n\\t// Copy this comment as an agent-ready prompt, with a brief checkmark confirm.\\n\\tlet copied = $state(false);\\n\\tlet copiedTimer: ReturnType<typeof setTimeout> | null = null;\\n\\tfunction copy(comment: PRReviewComment): void {\\n\\t\\tvoid actions.copyPRCommentPrompt(comment.path, comment.id);\\n\\t\\tcopied = true;\\n\\t\\tif (copiedTimer) clearTimeout(copiedTimer);\\n\\t\\tcopiedTimer = setTimeout(() => (copied = false), 1500);\\n\\t}\\n\\n\\tfunction toggleResolved(comment: PRReviewComment): void {\\n\\t\\t// No threadId means GraphQL didn't map this comment to a thread (e.g. a\\n\\t\\t// freshly created comment not yet refetched) — nothing to toggle.\\n\\t\\tif (!comment.threadId) return;\\n\\t\\tvoid actions.setThreadResolved(comment.threadId, !comment.isResolved);\\n\\t}\\n\\n\\tfunction onKeydown(e: KeyboardEvent): void {\\n\\t\\tif ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {\\n\\t\\t\\te.preventDefault();\\n\\t\\t\\tsubmit();\\n\\t\\t} else if (e.key === 'Escape') {\\n\\t\\t\\te.preventDefault();\\n\\t\\t\\tcancel();\\n\\t\\t}\\n\\t}\\n</script>\\n\\n<div class={['comment-annotation', isReply && 'is-reply']}>\\n\\t{#if meta.kind === 'comment'}\\n\\t\\t{@const c = meta.comment}\\n\\t\\t<!-- The thread root is the comment with no parent. Resolve controls and the\\n         \\\"Resolved\\\" badge live there so they appear once per thread, not on\\n         every reply (replies in a resolved thread are just dimmed). -->\\n\\t\\t{@const isRoot = !c.inReplyTo}\\n\\t\\t<article class=\\\"comment\\\">\\n\\t\\t\\t<img class=\\\"avatar\\\" src={c.authorAvatarUrl} alt={c.author} width=\\\"20\\\" height=\\\"20\\\" />\\n\\t\\t\\t<div class=\\\"body\\\">\\n\\t\\t\\t\\t<header>\\n\\t\\t\\t\\t\\t<span class=\\\"author\\\">{c.author}</span>\\n\\t\\t\\t\\t\\t<span class=\\\"time\\\">{formatRelative(c.createdAt)}</span>\\n\\t\\t\\t\\t\\t{#if c.isResolved && isRoot}\\n\\t\\t\\t\\t\\t\\t<span class=\\\"resolved-tag\\\"><Check class=\\\"size-3\\\" /> Resolved</span>\\n\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t<!-- Copy is always available; Delete stays tucked in an overflow menu\\n                 (shown only when the viewer can delete the comment). -->\\n\\t\\t\\t\\t\\t<div class=\\\"ml-auto flex shrink-0 items-center gap-0.5\\\">\\n\\t\\t\\t\\t\\t\\t<button\\n\\t\\t\\t\\t\\t\\t\\ttype=\\\"button\\\"\\n\\t\\t\\t\\t\\t\\t\\tclass=\\\"grid size-6 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground\\\"\\n\\t\\t\\t\\t\\t\\t\\ttitle=\\\"Copy as prompt\\\"\\n\\t\\t\\t\\t\\t\\t\\tonclick={() => copy(c)}\\n\\t\\t\\t\\t\\t\\t>\\n\\t\\t\\t\\t\\t\\t\\t{#if copied}\\n\\t\\t\\t\\t\\t\\t\\t\\t<Check class=\\\"size-3.5\\\" style=\\\"color: var(--color-success);\\\" />\\n\\t\\t\\t\\t\\t\\t\\t{:else}\\n\\t\\t\\t\\t\\t\\t\\t\\t<Copy class=\\\"size-3.5\\\" />\\n\\t\\t\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t\\t</button>\\n\\t\\t\\t\\t\\t\\t{#if c.canDelete}\\n\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Root>\\n\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Trigger\\n\\t\\t\\t\\t\\t\\t\\t\\t\\tclass=\\\"grid size-6 shrink-0 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground\\\"\\n\\t\\t\\t\\t\\t\\t\\t\\t\\taria-label=\\\"Comment actions\\\"\\n\\t\\t\\t\\t\\t\\t\\t\\t>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t<MoreHorizontal class=\\\"size-4\\\" />\\n\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Trigger>\\n\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Content align=\\\"end\\\">\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Item variant=\\\"destructive\\\" onSelect={() => remove(c)}>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<Trash2 class=\\\"size-3.5\\\" />\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tDelete\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Item>\\n\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Content>\\n\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Root>\\n\\t\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t</div>\\n\\t\\t\\t\\t</header>\\n\\t\\t\\t\\t{#if bodyHtml}\\n\\t\\t\\t\\t\\t<!-- bodyHtml is sanitized with DOMPurify in markdown.ts before it reaches here -->\\n\\t\\t\\t\\t\\t<!-- eslint-disable-next-line svelte/no-at-html-tags -->\\n\\t\\t\\t\\t\\t<div class=\\\"markdown-body text\\\">{@html bodyHtml}</div>\\n\\t\\t\\t\\t{:else}\\n\\t\\t\\t\\t\\t<p class=\\\"text\\\">{c.body}</p>\\n\\t\\t\\t\\t{/if}\\n\\t\\t\\t</div>\\n\\t\\t</article>\\n\\t\\t{#if isThreadTail}\\n\\t\\t\\t<!-- GitHub-style reply affordance: the viewer's avatar next to an inline\\n           input. Stays an input in place (no swap to a textarea) — submit on\\n           Enter. -->\\n\\t\\t\\t<form\\n\\t\\t\\t\\tclass=\\\"reply-prompt\\\"\\n\\t\\t\\t\\tonsubmit={(e) => {\\n\\t\\t\\t\\t\\te.preventDefault();\\n\\t\\t\\t\\t\\tvoid submitReply();\\n\\t\\t\\t\\t}}\\n\\t\\t\\t>\\n\\t\\t\\t\\t{#if viewerAvatar}\\n\\t\\t\\t\\t\\t<img class=\\\"reply-avatar\\\" src={viewerAvatar} alt=\\\"\\\" width=\\\"20\\\" height=\\\"20\\\" />\\n\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t<input\\n\\t\\t\\t\\t\\tclass=\\\"reply-box\\\"\\n\\t\\t\\t\\t\\ttype=\\\"text\\\"\\n\\t\\t\\t\\t\\tplaceholder=\\\"Reply…\\\"\\n\\t\\t\\t\\t\\tbind:value={replyDraft}\\n\\t\\t\\t\\t\\tdisabled={replySubmitting}\\n\\t\\t\\t\\t/>\\n\\t\\t\\t</form>\\n\\t\\t{/if}\\n\\t\\t{#if isThreadTail && c.threadId}\\n\\t\\t\\t<!-- Thread-level control: renders below the last comment so it sits\\n           under the whole conversation, mirroring GitHub's resolve bar. -->\\n\\t\\t\\t<div class=\\\"thread-actions\\\">\\n\\t\\t\\t\\t<Button variant=\\\"outline\\\" size=\\\"sm\\\" onclick={() => toggleResolved(c)}>\\n\\t\\t\\t\\t\\t{#if !c.isResolved}\\n\\t\\t\\t\\t\\t\\t<Check class=\\\"size-3.5\\\" />\\n\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t{c.isResolved ? 'Unresolve' : 'Resolve'}\\n\\t\\t\\t\\t</Button>\\n\\t\\t\\t</div>\\n\\t\\t{/if}\\n\\t{:else if composerState?.value}\\n\\t\\t{@const composer = composerState.value}\\n\\t\\t<form\\n\\t\\t\\tclass=\\\"composer\\\"\\n\\t\\t\\tonsubmit={(e) => {\\n\\t\\t\\t\\te.preventDefault();\\n\\t\\t\\t\\tsubmit();\\n\\t\\t\\t}}\\n\\t\\t>\\n\\t\\t\\t<div class=\\\"composer-header\\\">\\n\\t\\t\\t\\t<MessageSquare class=\\\"size-3.5 text-muted-foreground\\\" />\\n\\t\\t\\t\\t<span>{composer.replyTo ? 'Reply' : 'New comment'}</span>\\n\\t\\t\\t</div>\\n\\t\\t\\t<MarkdownComposer\\n\\t\\t\\t\\tbind:value={composer.draft}\\n\\t\\t\\t\\tplaceholder={composer.replyTo ? 'Write a reply…' : 'Leave a comment on this line…'}\\n\\t\\t\\t\\tdisabled={composer.submitting}\\n\\t\\t\\t\\tautofocus\\n\\t\\t\\t\\tonkeydown={onKeydown}\\n\\t\\t\\t/>\\n\\t\\t\\t<div class=\\\"composer-footer\\\">\\n\\t\\t\\t\\t<div class=\\\"actions\\\">\\n\\t\\t\\t\\t\\t<Button variant=\\\"ghost\\\" size=\\\"sm\\\" type=\\\"button\\\" onclick={cancel}>\\n\\t\\t\\t\\t\\t\\tCancel <kbd class=\\\"kbd\\\">esc</kbd>\\n\\t\\t\\t\\t\\t</Button>\\n\\t\\t\\t\\t\\t<Button\\n\\t\\t\\t\\t\\t\\tvariant=\\\"default\\\"\\n\\t\\t\\t\\t\\t\\tsize=\\\"sm\\\"\\n\\t\\t\\t\\t\\t\\ttype=\\\"submit\\\"\\n\\t\\t\\t\\t\\t\\tdisabled={!composer.draft.trim() || composer.submitting}\\n\\t\\t\\t\\t\\t>\\n\\t\\t\\t\\t\\t\\t{composer.submitting ? 'Posting…' : composer.replyTo ? 'Reply' : 'Comment'}\\n\\t\\t\\t\\t\\t\\t<kbd class=\\\"kbd\\\">⌘⏎</kbd>\\n\\t\\t\\t\\t\\t</Button>\\n\\t\\t\\t\\t</div>\\n\\t\\t\\t</div>\\n\\t\\t</form>\\n\\t{/if}\\n</div>\\n\\n<style>\\n\\t.comment-annotation {\\n\\t\\tpadding: 8px 12px;\\n\\t\\tbackground: hsl(var(--muted) / 0.4);\\n\\t\\tborder-top: 1px solid hsl(var(--border));\\n\\t\\tborder-bottom: 1px solid hsl(var(--border));\\n\\t\\tfont-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;\\n\\t}\\n\\t/* Divider between stacked comments in a thread: replies (every comment after\\n     the root) get a rule above them so each reads as a distinct entry. */\\n\\t.comment-annotation.is-reply {\\n\\t\\tborder-top: 1px solid var(--color-border);\\n\\t}\\n\\t.comment {\\n\\t\\tdisplay: grid;\\n\\t\\tgrid-template-columns: auto 1fr;\\n\\t\\tgap: 10px;\\n\\t\\talign-items: start;\\n\\t}\\n\\t/* GitHub-style reply affordance: avatar + an inline input that posts a reply\\n     directly (no swap to a separate composer). */\\n\\t.reply-prompt {\\n\\t\\tdisplay: flex;\\n\\t\\talign-items: center;\\n\\t\\tgap: 10px;\\n\\t\\twidth: 100%;\\n\\t\\tmargin-top: 10px;\\n\\t}\\n\\t.reply-avatar {\\n\\t\\tborder-radius: 999px;\\n\\t\\tflex-shrink: 0;\\n\\t}\\n\\t.reply-box {\\n\\t\\tflex: 1;\\n\\t\\tmin-width: 0;\\n\\t\\tpadding: 6px 10px;\\n\\t\\tfont: inherit;\\n\\t\\tfont-size: 13px;\\n\\t\\tcolor: var(--color-foreground);\\n\\t\\tbackground: var(--color-background);\\n\\t\\tborder: 1px solid var(--color-border);\\n\\t\\tborder-radius: 6px;\\n\\t\\toutline: none;\\n\\t}\\n\\t.reply-box::placeholder {\\n\\t\\tcolor: var(--color-muted-foreground);\\n\\t}\\n\\t.reply-box:focus {\\n\\t\\tborder-color: var(--color-ring);\\n\\t}\\n\\t.reply-box:disabled {\\n\\t\\topacity: 0.6;\\n\\t}\\n\\t/* Sits below the last comment, separated by a rule, so the resolve toggle\\n     reads as a thread-level action rather than part of that comment. Kept\\n     outside `.comment` so it stays full-opacity even when the thread is\\n     resolved (and its comments are dimmed). */\\n\\t.thread-actions {\\n\\t\\tdisplay: flex;\\n\\t\\tmargin-top: 10px;\\n\\t\\tpadding-top: 8px;\\n\\t\\tborder-top: 1px solid var(--color-border);\\n\\t}\\n\\t.resolved-tag {\\n\\t\\tdisplay: inline-flex;\\n\\t\\talign-items: center;\\n\\t\\tgap: 3px;\\n\\t\\tfont-size: 10px;\\n\\t\\tfont-weight: 600;\\n\\t\\tline-height: 1;\\n\\t\\tpadding: 2px 6px;\\n\\t\\tborder-radius: 999px;\\n\\t\\t/* Use the defined `--color-success` token (a full hsl() value); color-mix\\n       gives it a translucent fill — same approach used in DiffFileSection. */\\n\\t\\tbackground: color-mix(in srgb, var(--color-success) 15%, transparent);\\n\\t\\tcolor: var(--color-success);\\n\\t}\\n\\t.avatar {\\n\\t\\tborder-radius: 999px;\\n\\t\\tmargin-top: 2px;\\n\\t}\\n\\t.body header {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 8px;\\n\\t\\talign-items: center;\\n\\t\\tfont-size: 12px;\\n\\t}\\n\\t.author {\\n\\t\\tfont-weight: 600;\\n\\t}\\n\\t.time {\\n\\t\\tcolor: hsl(var(--muted-foreground));\\n\\t\\tfont-size: 11px;\\n\\t}\\n\\t.text {\\n\\t\\tfont-size: 13px;\\n\\t\\tline-height: 1.45;\\n\\t\\tmargin: 4px 0 6px;\\n\\t\\twhite-space: pre-wrap;\\n\\t\\tword-break: break-word;\\n\\t}\\n\\t.composer {\\n\\t\\tdisplay: flex;\\n\\t\\tflex-direction: column;\\n\\t\\tgap: 6px;\\n\\t}\\n\\t.composer-header {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 6px;\\n\\t\\talign-items: center;\\n\\t\\tfont-size: 12px;\\n\\t\\tcolor: hsl(var(--muted-foreground));\\n\\t}\\n\\t.composer-footer {\\n\\t\\tdisplay: flex;\\n\\t\\tjustify-content: flex-end;\\n\\t\\talign-items: center;\\n\\t}\\n\\t.actions {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 4px;\\n\\t}\\n\\t.kbd {\\n\\t\\tfont-family: inherit;\\n\\t\\tfont-size: 10px;\\n\\t\\tline-height: 1;\\n\\t\\tpadding: 2px 4px;\\n\\t\\tborder-radius: 4px;\\n\\t\\tbackground: hsl(var(--foreground) / 0.08);\\n\\t\\topacity: 0.7;\\n\\t}\\n</style>\\n\",\n      \"newContents\": \"<script lang=\\\"ts\\\">\\n\\timport { Check, Copy, Github, MessageSquare, MoreHorizontal, Trash2 } from 'lucide-svelte';\\n\\timport { Button } from './ui/button';\\n\\timport * as DropdownMenu from './ui/dropdown-menu';\\n\\timport MarkdownComposer from './MarkdownComposer.svelte';\\n\\timport { actions, app, composerKey, effectiveGithubAccount } from '$lib/store.svelte';\\n\\timport { formatRelative } from '$lib/utils';\\n\\timport { renderMarkdown } from '$lib/markdown';\\n\\timport '$lib/markdown.css';\\n\\timport type { PRReviewComment } from '@shared/types';\\n\\n\\t// Metadata stamped onto every DiffLineAnnotation we feed @pierre/diffs.\\n\\t// Lets this single component render either an existing comment row or the\\n\\t// pending composer for a brand-new comment / reply.\\n\\texport type CommentMeta =\\n\\t\\t| { kind: 'comment'; comment: PRReviewComment }\\n\\t\\t| {\\n\\t\\t\\t\\tkind: 'composer';\\n\\t\\t\\t\\tfilePath: string;\\n\\t\\t\\t\\tline: number;\\n\\t\\t\\t\\tside: 'LEFT' | 'RIGHT';\\n\\t\\t\\t\\treplyTo?: number;\\n\\t\\t  };\\n\\n\\tinterface Props {\\n\\t\\tmeta: CommentMeta;\\n\\t}\\n\\n\\tlet { meta }: Props = $props();\\n\\n\\t// Render the comment body as GitHub-Flavored Markdown (sanitized in\\n\\t// markdown.ts) so comments display formatted text, links, and code — matching\\n\\t// how the same markdown reads on GitHub — rather than as a raw string.\\n\\tlet bodyHtml = $state('');\\n\\t$effect(() => {\\n\\t\\tif (meta.kind !== 'comment') {\\n\\t\\t\\tbodyHtml = '';\\n\\t\\t\\treturn;\\n\\t\\t}\\n\\t\\tconst src = meta.comment.body;\\n\\t\\tconst theme = app.theme;\\n\\t\\tif (!src.trim()) {\\n\\t\\t\\tbodyHtml = '';\\n\\t\\t\\treturn;\\n\\t\\t}\\n\\t\\tlet cancelled = false;\\n\\t\\tvoid renderMarkdown(src, theme)\\n\\t\\t\\t.then((h) => {\\n\\t\\t\\t\\tif (!cancelled) bodyHtml = h;\\n\\t\\t\\t})\\n\\t\\t\\t.catch(() => {\\n\\t\\t\\t\\tif (!cancelled) bodyHtml = '';\\n\\t\\t\\t});\\n\\t\\treturn () => {\\n\\t\\t\\tcancelled = true;\\n\\t\\t};\\n\\t});\\n\\n\\tconst composerState = $derived.by(() => {\\n\\t\\tif (meta.kind !== 'composer') return null;\\n\\t\\tconst key = composerKey(meta.filePath, meta.side, meta.line);\\n\\t\\treturn { key, value: app.pendingComposers[key] ?? null };\\n\\t});\\n\\n\\t// All comments in this comment's thread (root + replies), in display order.\\n\\t// GitHub flattens replies so each carries the top-level comment's id in\\n\\t// `inReplyTo`; the root points at itself. We use this to anchor the\\n\\t// resolve/unresolve control to the LAST comment, so it renders once per\\n\\t// thread, below the whole conversation — not on an individual comment.\\n\\tconst threadComments = $derived.by(() => {\\n\\t\\tif (meta.kind !== 'comment') return [];\\n\\t\\tconst c = meta.comment;\\n\\t\\tconst rootId = c.inReplyTo ?? c.id;\\n\\t\\treturn (app.prComments[c.path] ?? []).filter((x) => (x.inReplyTo ?? x.id) === rootId);\\n\\t});\\n\\tconst isThreadTail = $derived(\\n\\t\\tmeta.kind === 'comment' && threadComments[threadComments.length - 1]?.id === meta.comment.id\\n\\t);\\n\\t// A reply (not the thread root) gets a divider above it so stacked comments\\n\\t// in a thread read as distinct entries rather than one run-on block.\\n\\tconst isReply = $derived(meta.kind === 'comment' && !!meta.comment.inReplyTo);\\n\\n\\t// The viewer's avatar for the GitHub-style reply prompt.\\n\\tconst viewerAvatar = $derived(effectiveGithubAccount()?.avatarUrl ?? '');\\n\\n\\t// Inline reply state. Kept local (not in pendingComposers) so the box stays\\n\\t// an input in place — no swap to a separate composer row, no layout shift.\\n\\tlet replyDraft = $state('');\\n\\tlet replySubmitting = $state(false);\\n\\n\\tfunction submit(): void {\\n\\t\\tif (composerState) void actions.submitComposer(composerState.key);\\n\\t}\\n\\n\\tfunction cancel(): void {\\n\\t\\tif (composerState) actions.cancelComposer(composerState.key);\\n\\t}\\n\\n\\t// Post a reply to the thread. Replies all hang off the top-level comment, so\\n\\t// we pass the root's id as `replyTo`.\\n\\tasync function submitReply(): Promise<void> {\\n\\t\\tif (meta.kind !== 'comment') return;\\n\\t\\tconst body = replyDraft.trim();\\n\\t\\tif (!body || replySubmitting) return;\\n\\t\\tconst c = meta.comment;\\n\\t\\tconst root = threadComments[0] ?? c;\\n\\t\\treplySubmitting = true;\\n\\t\\tconst ok = await actions.submitReply(c.path, root.id, body);\\n\\t\\treplySubmitting = false;\\n\\t\\tif (ok) replyDraft = '';\\n\\t}\\n\\n\\tfunction remove(comment: PRReviewComment): void {\\n\\t\\tvoid actions.deleteComment(comment.id, comment.path);\\n\\t}\\n\\n\\t// Open this comment on GitHub in the user's browser. `url` is the API-provided\\n\\t// permalink to the review comment.\\n\\tfunction viewOnGithub(comment: PRReviewComment): void {\\n\\t\\tif (!comment.url) return;\\n\\t\\tvoid window.api.shell.openExternal(comment.url);\\n\\t}\\n\\n\\t// Copy this comment as an agent-ready prompt, with a brief checkmark confirm.\\n\\tlet copied = $state(false);\\n\\tlet copiedTimer: ReturnType<typeof setTimeout> | null = null;\\n\\tfunction copy(comment: PRReviewComment): void {\\n\\t\\tvoid actions.copyPRCommentPrompt(comment.path, comment.id);\\n\\t\\tcopied = true;\\n\\t\\tif (copiedTimer) clearTimeout(copiedTimer);\\n\\t\\tcopiedTimer = setTimeout(() => (copied = false), 1500);\\n\\t}\\n\\n\\tfunction toggleResolved(comment: PRReviewComment): void {\\n\\t\\t// No threadId means GraphQL didn't map this comment to a thread (e.g. a\\n\\t\\t// freshly created comment not yet refetched) — nothing to toggle.\\n\\t\\tif (!comment.threadId) return;\\n\\t\\tvoid actions.setThreadResolved(comment.threadId, !comment.isResolved);\\n\\t}\\n\\n\\tfunction onKeydown(e: KeyboardEvent): void {\\n\\t\\tif ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {\\n\\t\\t\\te.preventDefault();\\n\\t\\t\\tsubmit();\\n\\t\\t} else if (e.key === 'Escape') {\\n\\t\\t\\te.preventDefault();\\n\\t\\t\\tcancel();\\n\\t\\t}\\n\\t}\\n</script>\\n\\n<div class={['comment-annotation', isReply && 'is-reply']}>\\n\\t{#if meta.kind === 'comment'}\\n\\t\\t{@const c = meta.comment}\\n\\t\\t<!-- The thread root is the comment with no parent. Resolve controls and the\\n         \\\"Resolved\\\" badge live there so they appear once per thread, not on\\n         every reply (replies in a resolved thread are just dimmed). -->\\n\\t\\t{@const isRoot = !c.inReplyTo}\\n\\t\\t<article class=\\\"comment\\\">\\n\\t\\t\\t<img class=\\\"avatar\\\" src={c.authorAvatarUrl} alt={c.author} width=\\\"20\\\" height=\\\"20\\\" />\\n\\t\\t\\t<div class=\\\"body\\\">\\n\\t\\t\\t\\t<header>\\n\\t\\t\\t\\t\\t<span class=\\\"author\\\">{c.author}</span>\\n\\t\\t\\t\\t\\t<span class=\\\"time\\\">{formatRelative(c.createdAt)}</span>\\n\\t\\t\\t\\t\\t{#if c.isResolved && isRoot}\\n\\t\\t\\t\\t\\t\\t<span class=\\\"resolved-tag\\\"><Check class=\\\"size-3\\\" /> Resolved</span>\\n\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t<!-- Copy is always available; Delete stays tucked in an overflow menu\\n                 (shown only when the viewer can delete the comment). -->\\n\\t\\t\\t\\t\\t<div class=\\\"ml-auto flex shrink-0 items-center gap-0.5\\\">\\n\\t\\t\\t\\t\\t\\t<button\\n\\t\\t\\t\\t\\t\\t\\ttype=\\\"button\\\"\\n\\t\\t\\t\\t\\t\\t\\tclass=\\\"grid size-6 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground\\\"\\n\\t\\t\\t\\t\\t\\t\\ttitle=\\\"Copy as prompt\\\"\\n\\t\\t\\t\\t\\t\\t\\tonclick={() => copy(c)}\\n\\t\\t\\t\\t\\t\\t>\\n\\t\\t\\t\\t\\t\\t\\t{#if copied}\\n\\t\\t\\t\\t\\t\\t\\t\\t<Check class=\\\"size-3.5\\\" style=\\\"color: var(--color-success);\\\" />\\n\\t\\t\\t\\t\\t\\t\\t{:else}\\n\\t\\t\\t\\t\\t\\t\\t\\t<Copy class=\\\"size-3.5\\\" />\\n\\t\\t\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t\\t</button>\\n\\t\\t\\t\\t\\t\\t{#if c.url || c.canDelete}\\n\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Root>\\n\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Trigger\\n\\t\\t\\t\\t\\t\\t\\t\\t\\tclass=\\\"grid size-6 shrink-0 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground\\\"\\n\\t\\t\\t\\t\\t\\t\\t\\t\\taria-label=\\\"Comment actions\\\"\\n\\t\\t\\t\\t\\t\\t\\t\\t>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t<MoreHorizontal class=\\\"size-4\\\" />\\n\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Trigger>\\n\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Content align=\\\"end\\\">\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t{#if c.url}\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Item onSelect={() => viewOnGithub(c)}>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<Github class=\\\"size-3.5\\\" />\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tView on GitHub\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Item>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t{#if c.canDelete}\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t{#if c.url}\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Separator />\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Item variant=\\\"destructive\\\" onSelect={() => remove(c)}>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<Trash2 class=\\\"size-3.5\\\" />\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tDelete\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Item>\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Content>\\n\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Root>\\n\\t\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t</div>\\n\\t\\t\\t\\t</header>\\n\\t\\t\\t\\t{#if bodyHtml}\\n\\t\\t\\t\\t\\t<!-- bodyHtml is sanitized with DOMPurify in markdown.ts before it reaches here -->\\n\\t\\t\\t\\t\\t<!-- eslint-disable-next-line svelte/no-at-html-tags -->\\n\\t\\t\\t\\t\\t<div class=\\\"markdown-body text\\\">{@html bodyHtml}</div>\\n\\t\\t\\t\\t{:else}\\n\\t\\t\\t\\t\\t<p class=\\\"text\\\">{c.body}</p>\\n\\t\\t\\t\\t{/if}\\n\\t\\t\\t</div>\\n\\t\\t</article>\\n\\t\\t{#if isThreadTail}\\n\\t\\t\\t<!-- GitHub-style reply affordance: the viewer's avatar next to an inline\\n           input. Stays an input in place (no swap to a textarea) — submit on\\n           Enter. -->\\n\\t\\t\\t<form\\n\\t\\t\\t\\tclass=\\\"reply-prompt\\\"\\n\\t\\t\\t\\tonsubmit={(e) => {\\n\\t\\t\\t\\t\\te.preventDefault();\\n\\t\\t\\t\\t\\tvoid submitReply();\\n\\t\\t\\t\\t}}\\n\\t\\t\\t>\\n\\t\\t\\t\\t{#if viewerAvatar}\\n\\t\\t\\t\\t\\t<img class=\\\"reply-avatar\\\" src={viewerAvatar} alt=\\\"\\\" width=\\\"20\\\" height=\\\"20\\\" />\\n\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t<input\\n\\t\\t\\t\\t\\tclass=\\\"reply-box\\\"\\n\\t\\t\\t\\t\\ttype=\\\"text\\\"\\n\\t\\t\\t\\t\\tplaceholder=\\\"Reply…\\\"\\n\\t\\t\\t\\t\\tbind:value={replyDraft}\\n\\t\\t\\t\\t\\tdisabled={replySubmitting}\\n\\t\\t\\t\\t/>\\n\\t\\t\\t</form>\\n\\t\\t{/if}\\n\\t\\t{#if isThreadTail && c.threadId}\\n\\t\\t\\t<!-- Thread-level control: renders below the last comment so it sits\\n           under the whole conversation, mirroring GitHub's resolve bar. -->\\n\\t\\t\\t<div class=\\\"thread-actions\\\">\\n\\t\\t\\t\\t<Button variant=\\\"outline\\\" size=\\\"sm\\\" onclick={() => toggleResolved(c)}>\\n\\t\\t\\t\\t\\t{#if !c.isResolved}\\n\\t\\t\\t\\t\\t\\t<Check class=\\\"size-3.5\\\" />\\n\\t\\t\\t\\t\\t{/if}\\n\\t\\t\\t\\t\\t{c.isResolved ? 'Unresolve' : 'Resolve'}\\n\\t\\t\\t\\t</Button>\\n\\t\\t\\t</div>\\n\\t\\t{/if}\\n\\t{:else if composerState?.value}\\n\\t\\t{@const composer = composerState.value}\\n\\t\\t<form\\n\\t\\t\\tclass=\\\"composer\\\"\\n\\t\\t\\tonsubmit={(e) => {\\n\\t\\t\\t\\te.preventDefault();\\n\\t\\t\\t\\tsubmit();\\n\\t\\t\\t}}\\n\\t\\t>\\n\\t\\t\\t<div class=\\\"composer-header\\\">\\n\\t\\t\\t\\t<MessageSquare class=\\\"size-3.5 text-muted-foreground\\\" />\\n\\t\\t\\t\\t<span>{composer.replyTo ? 'Reply' : 'New comment'}</span>\\n\\t\\t\\t</div>\\n\\t\\t\\t<MarkdownComposer\\n\\t\\t\\t\\tbind:value={composer.draft}\\n\\t\\t\\t\\tplaceholder={composer.replyTo ? 'Write a reply…' : 'Leave a comment on this line…'}\\n\\t\\t\\t\\tdisabled={composer.submitting}\\n\\t\\t\\t\\tautofocus\\n\\t\\t\\t\\tonkeydown={onKeydown}\\n\\t\\t\\t/>\\n\\t\\t\\t<div class=\\\"composer-footer\\\">\\n\\t\\t\\t\\t<div class=\\\"actions\\\">\\n\\t\\t\\t\\t\\t<Button variant=\\\"ghost\\\" size=\\\"sm\\\" type=\\\"button\\\" onclick={cancel}>\\n\\t\\t\\t\\t\\t\\tCancel <kbd class=\\\"kbd\\\">esc</kbd>\\n\\t\\t\\t\\t\\t</Button>\\n\\t\\t\\t\\t\\t<Button\\n\\t\\t\\t\\t\\t\\tvariant=\\\"default\\\"\\n\\t\\t\\t\\t\\t\\tsize=\\\"sm\\\"\\n\\t\\t\\t\\t\\t\\ttype=\\\"submit\\\"\\n\\t\\t\\t\\t\\t\\tdisabled={!composer.draft.trim() || composer.submitting}\\n\\t\\t\\t\\t\\t>\\n\\t\\t\\t\\t\\t\\t{composer.submitting ? 'Posting…' : composer.replyTo ? 'Reply' : 'Comment'}\\n\\t\\t\\t\\t\\t\\t<kbd class=\\\"kbd\\\">⌘⏎</kbd>\\n\\t\\t\\t\\t\\t</Button>\\n\\t\\t\\t\\t</div>\\n\\t\\t\\t</div>\\n\\t\\t</form>\\n\\t{/if}\\n</div>\\n\\n<style>\\n\\t.comment-annotation {\\n\\t\\tpadding: 8px 12px;\\n\\t\\tbackground: hsl(var(--muted) / 0.4);\\n\\t\\tborder-top: 1px solid hsl(var(--border));\\n\\t\\tborder-bottom: 1px solid hsl(var(--border));\\n\\t\\tfont-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;\\n\\t}\\n\\t/* Divider between stacked comments in a thread: replies (every comment after\\n     the root) get a rule above them so each reads as a distinct entry. */\\n\\t.comment-annotation.is-reply {\\n\\t\\tborder-top: 1px solid var(--color-border);\\n\\t}\\n\\t.comment {\\n\\t\\tdisplay: grid;\\n\\t\\tgrid-template-columns: auto 1fr;\\n\\t\\tgap: 10px;\\n\\t\\talign-items: start;\\n\\t}\\n\\t/* GitHub-style reply affordance: avatar + an inline input that posts a reply\\n     directly (no swap to a separate composer). */\\n\\t.reply-prompt {\\n\\t\\tdisplay: flex;\\n\\t\\talign-items: center;\\n\\t\\tgap: 10px;\\n\\t\\twidth: 100%;\\n\\t\\tmargin-top: 4px;\\n\\t}\\n\\t.reply-avatar {\\n\\t\\tborder-radius: 999px;\\n\\t\\tflex-shrink: 0;\\n\\t}\\n\\t.reply-box {\\n\\t\\tflex: 1;\\n\\t\\tmin-width: 0;\\n\\t\\tpadding: 6px 10px;\\n\\t\\tfont: inherit;\\n\\t\\tfont-size: 13px;\\n\\t\\tcolor: var(--color-foreground);\\n\\t\\tbackground: var(--color-background);\\n\\t\\tborder: 1px solid var(--color-border);\\n\\t\\tborder-radius: 6px;\\n\\t\\toutline: none;\\n\\t}\\n\\t.reply-box::placeholder {\\n\\t\\tcolor: var(--color-muted-foreground);\\n\\t}\\n\\t.reply-box:focus {\\n\\t\\tborder-color: var(--color-ring);\\n\\t}\\n\\t.reply-box:disabled {\\n\\t\\topacity: 0.6;\\n\\t}\\n\\t/* Sits below the last comment, separated by a rule, so the resolve toggle\\n     reads as a thread-level action rather than part of that comment. Kept\\n     outside `.comment` so it stays full-opacity even when the thread is\\n     resolved (and its comments are dimmed). */\\n\\t.thread-actions {\\n\\t\\tdisplay: flex;\\n\\t\\tmargin-top: 6px;\\n\\t\\tpadding-top: 6px;\\n\\t\\tborder-top: 1px solid var(--color-border);\\n\\t}\\n\\t.resolved-tag {\\n\\t\\tdisplay: inline-flex;\\n\\t\\talign-items: center;\\n\\t\\tgap: 3px;\\n\\t\\tfont-size: 10px;\\n\\t\\tfont-weight: 600;\\n\\t\\tline-height: 1;\\n\\t\\tpadding: 2px 6px;\\n\\t\\tborder-radius: 999px;\\n\\t\\t/* Use the defined `--color-success` token (a full hsl() value); color-mix\\n       gives it a translucent fill — same approach used in DiffFileSection. */\\n\\t\\tbackground: color-mix(in srgb, var(--color-success) 15%, transparent);\\n\\t\\tcolor: var(--color-success);\\n\\t}\\n\\t.avatar {\\n\\t\\tborder-radius: 999px;\\n\\t\\tmargin-top: 2px;\\n\\t}\\n\\t.body header {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 8px;\\n\\t\\talign-items: center;\\n\\t\\tfont-size: 12px;\\n\\t}\\n\\t.author {\\n\\t\\tfont-weight: 600;\\n\\t}\\n\\t.time {\\n\\t\\tcolor: hsl(var(--muted-foreground));\\n\\t\\tfont-size: 11px;\\n\\t}\\n\\t.text {\\n\\t\\tfont-size: 13px;\\n\\t\\tline-height: 1.45;\\n\\t\\tmargin: 4px 0 6px;\\n\\t\\twhite-space: pre-wrap;\\n\\t\\tword-break: break-word;\\n\\t}\\n\\t.composer {\\n\\t\\tdisplay: flex;\\n\\t\\tflex-direction: column;\\n\\t\\tgap: 6px;\\n\\t}\\n\\t.composer-header {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 6px;\\n\\t\\talign-items: center;\\n\\t\\tfont-size: 12px;\\n\\t\\tcolor: hsl(var(--muted-foreground));\\n\\t}\\n\\t.composer-footer {\\n\\t\\tdisplay: flex;\\n\\t\\tjustify-content: flex-end;\\n\\t\\talign-items: center;\\n\\t}\\n\\t.actions {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 4px;\\n\\t}\\n\\t.kbd {\\n\\t\\tfont-family: inherit;\\n\\t\\tfont-size: 10px;\\n\\t\\tline-height: 1;\\n\\t\\tpadding: 2px 4px;\\n\\t\\tborder-radius: 4px;\\n\\t\\tbackground: hsl(var(--foreground) / 0.08);\\n\\t\\topacity: 0.7;\\n\\t}\\n</style>\\n\",\n      \"truncated\": false\n    }\n  ]\n}",
