\\n\\t\\t\\t\\t</div>\\n\\t\\t\\t</div>\\n\\t\\t</form>\\n\\t{/if}\\n</div>\\n\\n<style>\\n\\t.comment-annotation {\\n\\t\\tpadding: 8px 12px;\\n\\t\\tbackground: hsl(var(--muted) / 0.4);\\n\\t\\tborder-top: 1px solid hsl(var(--border));\\n\\t\\tborder-bottom: 1px solid hsl(var(--border));\\n\\t\\tfont-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;\\n\\t}\\n\\t/* Divider between stacked comments in a thread: replies (every comment after\\n     the root) get a rule above them so each reads as a distinct entry. */\\n\\t.comment-annotation.is-reply {\\n\\t\\tborder-top: 1px solid var(--color-border);\\n\\t}\\n\\t.comment {\\n\\t\\tdisplay: grid;\\n\\t\\tgrid-template-columns: auto 1fr;\\n\\t\\tgap: 10px;\\n\\t\\talign-items: start;\\n\\t}\\n\\t/* GitHub-style reply affordance: avatar + an inline input that posts a reply\\n     directly (no swap to a separate composer). */\\n\\t.reply-prompt {\\n\\t\\tdisplay: flex;\\n\\t\\talign-items: center;\\n\\t\\tgap: 10px;\\n\\t\\twidth: 100%;\\n\\t\\tmargin-top: 4px;\\n\\t}\\n\\t.reply-avatar {\\n\\t\\tborder-radius: 999px;\\n\\t\\tflex-shrink: 0;\\n\\t}\\n\\t.reply-box {\\n\\t\\tflex: 1;\\n\\t\\tmin-width: 0;\\n\\t\\tpadding: 6px 10px;\\n\\t\\tfont: inherit;\\n\\t\\tfont-size: 13px;\\n\\t\\tcolor: var(--color-foreground);\\n\\t\\tbackground: var(--color-background);\\n\\t\\tborder: 1px solid var(--color-border);\\n\\t\\tborder-radius: 6px;\\n\\t\\toutline: none;\\n\\t}\\n\\t.reply-box::placeholder {\\n\\t\\tcolor: var(--color-muted-foreground);\\n\\t}\\n\\t.reply-box:focus {\\n\\t\\tborder-color: var(--color-ring);\\n\\t}\\n\\t.reply-box:disabled {\\n\\t\\topacity: 0.6;\\n\\t}\\n\\t/* Sits below the last comment, separated by a rule, so the resolve toggle\\n     reads as a thread-level action rather than part of that comment. Kept\\n     outside `.comment` so it stays full-opacity even when the thread is\\n     resolved (and its comments are dimmed). */\\n\\t.thread-actions {\\n\\t\\tdisplay: flex;\\n\\t\\tmargin-top: 6px;\\n\\t\\tpadding-top: 6px;\\n\\t\\tborder-top: 1px solid var(--color-border);\\n\\t}\\n\\t.resolved-tag {\\n\\t\\tdisplay: inline-flex;\\n\\t\\talign-items: center;\\n\\t\\tgap: 3px;\\n\\t\\tfont-size: 10px;\\n\\t\\tfont-weight: 600;\\n\\t\\tline-height: 1;\\n\\t\\tpadding: 2px 6px;\\n\\t\\tborder-radius: 999px;\\n\\t\\t/* Use the defined `--color-success` token (a full hsl() value); color-mix\\n       gives it a translucent fill — same approach used in DiffFileSection. */\\n\\t\\tbackground: color-mix(in srgb, var(--color-success) 15%, transparent);\\n\\t\\tcolor: var(--color-success);\\n\\t}\\n\\t.avatar {\\n\\t\\tborder-radius: 999px;\\n\\t\\tmargin-top: 2px;\\n\\t}\\n\\t.body header {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 8px;\\n\\t\\talign-items: center;\\n\\t\\tfont-size: 12px;\\n\\t}\\n\\t.author {\\n\\t\\tfont-weight: 600;\\n\\t}\\n\\t.time {\\n\\t\\tcolor: hsl(var(--muted-foreground));\\n\\t\\tfont-size: 11px;\\n\\t}\\n\\t.text {\\n\\t\\tfont-size: 13px;\\n\\t\\tline-height: 1.45;\\n\\t\\tmargin: 4px 0 6px;\\n\\t\\twhite-space: pre-wrap;\\n\\t\\tword-break: break-word;\\n\\t}\\n\\t.composer {\\n\\t\\tdisplay: flex;\\n\\t\\tflex-direction: column;\\n\\t\\tgap: 6px;\\n\\t}\\n\\t.composer-header {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 6px;\\n\\t\\talign-items: center;\\n\\t\\tfont-size: 12px;\\n\\t\\tcolor: hsl(var(--muted-foreground));\\n\\t}\\n\\t.composer-footer {\\n\\t\\tdisplay: flex;\\n\\t\\tjustify-content: flex-end;\\n\\t\\talign-items: center;\\n\\t}\\n\\t.actions {\\n\\t\\tdisplay: flex;\\n\\t\\tgap: 4px;\\n\\t}\\n\\t.kbd {\\n\\t\\tfont-family: inherit;\\n\\t\\tfont-size: 10px;\\n\\t\\tline-height: 1;\\n\\t\\tpadding: 2px 4px;\\n\\t\\tborder-radius: 4px;\\n\\t\\tbackground: hsl(var(--foreground) / 0.08);\\n\\t\\topacity: 0.7;\\n\\t}\\n</style>\\n\",\n+      \"truncated\": false\n+    }\n+  ]\n+}\n\\ No newline at end of file\n",
+      "oldContents": "",
+      "newContents": "{\n  \"id\": \"e314794d-bf7c-4fc6-a27a-347dc79901de\",\n  \"repoId\": \"6f999874a296\",\n  \"key\": \"comment-annotation-polish-d2mvd\",\n  \"name\": \"Comment annotation polish: tighter spacing + View on GitHub\",\n  \"description\": \"Two tweaks to the inline PR comment thread: tightened the vertical whitespace around the reply box, and added a \\\"View on GitHub\\\" item to each comment's overflow menu.\",\n  \"harness\": \"claude-code\",\n  \"branch\": \"claude/modest-brahmagupta-d2mvd\",\n  \"baseRef\": \"8f02e55fe4ea353fff08a83a7f0fb36f2417846c\",\n  \"createdAt\": 1780668125104,\n  \"updatedAt\": 1780668125104,\n  \"fileCount\": 1,\n  \"additions\": 27,\n  \"deletions\": 9,\n  \"stepCount\": 2,\n  \"steps\": [\n    {\n      \"id\": \"step-1\",\n      \"title\": \"Tighten reply-box spacing\",\n      \"body\": \"The reply box had ~16px of dead space above it and ~18px below before the Resolve bar. Verified the exact gaps with an isolated repro (the gap is pure CSS margin, no hidden markdown element). Cut the reply box's top margin to **4px** and the thread-actions bar to **6px** margin + **6px** padding, keeping the divider rule.\",\n      \"paths\": [\n        \"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\"\n      ],\n      \"callouts\": [\n        {\n          \"id\": \"step-1-c1\",\n          \"file\": \"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\",\n          \"startLine\": 322,\n          \"endLine\": 322,\n          \"side\": \"new\",\n          \"body\": \"Gap above the reply box: was 10px (total 16px with .text margin-bottom), now 4px.\"\n        },\n        {\n          \"id\": \"step-1-c2\",\n          \"file\": \"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\",\n          \"startLine\": 355,\n          \"endLine\": 356,\n          \"side\": \"new\",\n          \"body\": \"Gap below the reply box, before Resolve: was 10px margin + 8px padding, now 6px + 6px.\"\n        }\n      ]\n    },\n    {\n      \"id\": \"step-2\",\n      \"title\": \"Add \\\"View on GitHub\\\" to the comment menu\",\n      \"body\": \"The overflow (•••) menu previously only rendered when the comment was deletable. Now it always renders so every comment exposes **View on GitHub**, which opens the comment's API permalink (`comment.url`) via `window.api.shell.openExternal`. Delete stays, moved behind a separator when the viewer can delete.\",\n      \"paths\": [\n        \"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\"\n      ],\n      \"callouts\": [\n        {\n          \"id\": \"step-2-c1\",\n          \"file\": \"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\",\n          \"startLine\": 117,\n          \"endLine\": 122,\n          \"side\": \"new\",\n          \"body\": \"Opens the comment permalink in the browser; no-ops if url is empty (e.g. a just-created comment not yet refetched).\"\n        },\n        {\n          \"id\": \"step-2-c2\",\n          \"file\": \"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\",\n          \"startLine\": 192,\n          \"endLine\": 197,\n          \"side\": \"new\",\n          \"body\": \"New menu item, gated on c.url so it only shows when there's a permalink to open.\"\n        }\n      ]\n    }\n  ],\n  \"files\": [\n    {\n      \"path\": \"apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\",\n      \"status\": \"modified\",\n      \"additions\": 27,\n      \"deletions\": 9,\n      \"isBinary\": false,\n      \"patch\": \"diff --git a/apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte b/apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\nindex bdf683fd..09f71108 100644\\n--- a/apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\n+++ b/apps/desktop/src/renderer/src/lib/components/CommentAnnotation.svelte\\n@@ -1,5 +1,5 @@\\n <script lang=\\\"ts\\\">\\n-\\timport { Check, Copy, MessageSquare, MoreHorizontal, Trash2 } from 'lucide-svelte';\\n+\\timport { Check, Copy, Github, MessageSquare, MoreHorizontal, Trash2 } from 'lucide-svelte';\\n \\timport { Button } from './ui/button';\\n \\timport * as DropdownMenu from './ui/dropdown-menu';\\n \\timport MarkdownComposer from './MarkdownComposer.svelte';\\n@@ -114,6 +114,13 @@\\n \\t\\tvoid actions.deleteComment(comment.id, comment.path);\\n \\t}\\n \\n+\\t// Open this comment on GitHub in the user's browser. `url` is the API-provided\\n+\\t// permalink to the review comment.\\n+\\tfunction viewOnGithub(comment: PRReviewComment): void {\\n+\\t\\tif (!comment.url) return;\\n+\\t\\tvoid window.api.shell.openExternal(comment.url);\\n+\\t}\\n+\\n \\t// Copy this comment as an agent-ready prompt, with a brief checkmark confirm.\\n \\tlet copied = $state(false);\\n \\tlet copiedTimer: ReturnType<typeof setTimeout> | null = null;\\n@@ -173,7 +180,7 @@\\n \\t\\t\\t\\t\\t\\t\\t\\t<Copy class=\\\"size-3.5\\\" />\\n \\t\\t\\t\\t\\t\\t\\t{/if}\\n \\t\\t\\t\\t\\t\\t</button>\\n-\\t\\t\\t\\t\\t\\t{#if c.canDelete}\\n+\\t\\t\\t\\t\\t\\t{#if c.url || c.canDelete}\\n \\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Root>\\n \\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Trigger\\n \\t\\t\\t\\t\\t\\t\\t\\t\\tclass=\\\"grid size-6 shrink-0 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground\\\"\\n@@ -182,10 +189,21 @@\\n \\t\\t\\t\\t\\t\\t\\t\\t\\t<MoreHorizontal class=\\\"size-4\\\" />\\n \\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Trigger>\\n \\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Content align=\\\"end\\\">\\n-\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Item variant=\\\"destructive\\\" onSelect={() => remove(c)}>\\n-\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<Trash2 class=\\\"size-3.5\\\" />\\n-\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tDelete\\n-\\t\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Item>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t{#if c.url}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Item onSelect={() => viewOnGithub(c)}>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<Github class=\\\"size-3.5\\\" />\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tView on GitHub\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Item>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t{#if c.canDelete}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t{#if c.url}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Separator />\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<DropdownMenu.Item variant=\\\"destructive\\\" onSelect={() => remove(c)}>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<Trash2 class=\\\"size-3.5\\\" />\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tDelete\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Item>\\n+\\t\\t\\t\\t\\t\\t\\t\\t\\t{/if}\\n \\t\\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Content>\\n \\t\\t\\t\\t\\t\\t\\t</DropdownMenu.Root>\\n \\t\\t\\t\\t\\t\\t{/if}\\n@@ -301,7 +319,7 @@\\n \\t\\talign-items: center;\\n \\t\\tgap: 10px;\\n \\t\\twidth: 100%;\\n-\\t\\tmargin-top: 10px;\\n+\\t\\tmargin-top: 4px;\\n \\t}\\n \\t.reply-avatar {\\n \\t\\tborder-radius: 999px;\\n@@ -334,8 +352,8 @@\\n      resolved (and its comments are dimmed). */\\n \\t.thread-actions {\\n \\t\\tdisplay: flex;\\n-\\t\\tmargin-top: 10px;\\n-\\t\\tpadding-top: 8px;\\n+\\t\\tmargin-top: 6px;\\n+\\t\\tpadding-top: 6px;\\n \\t\\tborder-top: 1px solid var(--color-border);\\n \\t}\\n \\t.resolved-tag {\\n\",\n      \"oldContents\": \"<script lang=\\\"ts\\\">\\n\\timport { Check, Copy, MessageSquare, MoreHorizontal, Trash2 } from 'lucide-svelte';\\n\\timport { Button } from './ui/button';\\n\\timport * as DropdownMenu from './ui/dropdown-menu';\\n\\timport MarkdownComposer from './MarkdownComposer.svelte';\\n\\timport { actions, app, composerKey, effectiveGithubAccount } from '$lib/store.svelte';\\n\\timport { formatRelative } from '$lib/utils';\\n\\timport { renderMarkdown } from '$lib/markdown';\\n\\timport '$lib/markdown.css';\\n\\timport type { PRReviewComment } from '@shared/types';\\n\\n\\t// Metadata stamped onto every DiffLineAnnotation we feed @pierre/diffs.\\n\\t// Lets this single component render either an existing comment row or the\\n\\t// pending composer for a brand-new comment / reply.\\n\\texport type CommentMeta =\\n\\t\\t| { kind: 'comment'; comment: PRReviewComment }\\n\\t\\t| {\\n\\t\\t\\t\\tkind: 'composer';\\n\\t\\t\\t\\tfilePath: string;\\n\\t\\t\\t\\tline: number;\\n\\t\\t\\t\\tside: 'LEFT' | 'RIGHT';\\n\\t\\t\\t\\treplyTo?: number;\\n\\t\\t  };\\n\\n\\tinterface Props {\\n\\t\\tmeta: CommentMeta;\\n\\t}\\n\\n\\tlet { meta }: Props = $props();\\n\\n\\t// Render the comment body as GitHub-Flavored Markdown (sanitized in\\n\\t// markdown.ts) so comments display formatted text, links, and code — matching\\n\\t// how the same markdown reads on GitHub — rather than as a raw string.\\n\\tlet bodyHtml = $state('');\\n\\t$effect(() => {\\n\\t\\tif (meta.kind !== 'comment') {\\n\\t\\t\\tbodyHtml = '';\\n\\t\\t\\treturn;\\n\\t\\t}\\n\\t\\tconst src = meta.comment.body;\\n\\t\\tconst theme = app.theme;\\n\\t\\tif (!src.trim()) {\\n\\t\\t\\tbodyHtml = '';\\n\\t\\t\\treturn;\\n\\t\\t}\\n\\t\\tlet cancelled = false;\\n\\t\\tvoid renderMarkdown(src, theme)\\n\\t\\t\\t.then((h) => {\\n\\t\\t\\t\\tif (!cancelled) bodyHtml = h;\\n\\t\\t\\t})\\n\\t\\t\\t.catch(() => {\\n\\t\\t\\t\\tif (!cancelled) bodyHtml = '';\\n\\t\\t\\t});\\n\\t\\treturn () => {\\n\\t\\t\\tcancelled = true;\\n\\t\\t};\\n\\t});\\n\\n\\tconst composerState = $derived.by(() => {\\n\\t\\tif (meta.kind !== 'composer') return null;\\n\\t\\tconst key = composerKey(meta.filePath, meta.side, meta.line);\\n\\t\\treturn { key, value: app.pendingComposers[key] ?? null };\\n\\t});\\n\\n\\t// All comments in this comment's thread (root + replies), in display order.\\n\\t// GitHub flattens replies so each carries the top-level comment's id in\\n\\t// `inReplyTo`; the root points at itself. We use this to anchor the\\n\\t// resolve/unresolve control to the LAST comment, so it renders once per\\n\\t// thread, below the whole conversation — not on an individual comment.\\n\\tconst threadComments = $derived.by(() => {\\n\\t\\tif (meta.kind !== 'comment') return [];\\n\\t\\tconst c = meta.comment;\\n\\t\\tconst rootId = c.inReplyTo ?? c.id;\\n\\t\\treturn (app.prComments[c.path] ?? []).filter((x) => (x.inReplyTo ?? x.id) === rootId);\\n\\t});\\n\\tconst isThreadTail = $derived(\\n\\t\\tmeta.kind === 'comment' && threadComments[threadComments.length - 1]?.id === meta.comment.id\\n\\t);\\n\\t// A reply (not the thread root) gets a divider above it so stacked comments\\n\\t// in a thread read as distinct entries rather than one run-on block.\\n\\tconst isReply = $derived(meta.kind === 'comment' && !!meta.comment.inReplyTo);\\n\\n\\t// The viewer's avatar for the GitHub-style reply prompt.\\n\\tconst viewerAvatar = $derived(effectiveGithubAccount()?.avatarUrl ?? '');\\n\\n\\t// Inline reply state. Kept local (not in pendingComposers) so the box stays\\n\\t// an input in place — no swap to a separate composer row, no layout shift.\\n\\tlet replyDraft = $state('');\\n\\tlet replySubmitting = $state(false);\\n\\n\\tfunction submit(): void {\\n\\t\\tif (composerState) void actions.submitComposer(composerState.key);\\n\\t}\\n\\n\\tfunction cancel(): void {\\n\\t\\tif (composerState) actions.cancelComposer(composerState.key);\\n\\t}\\n\\n\\t// Post a reply to the thread. Replies all hang off the top-level comment, so\\n\\t// we pass the root's id as `replyTo`.\\n\\tasync function submitReply(): Promise<void> {\\n\\t\\tif (meta.kind !== 'comment') return;\\n\\t\\tconst body = replyDraft.trim();\\n\\t\\tif (!body || replySubmitting) return;\\n\\t\\tconst c = meta.comment;\\n\\t\\tconst root = threadComments[0] ?? c;\\n\\t\\treplySubmitting = true;\\n\\t\\tconst ok = await actions.submitReply(c.path, root.id, body);\\n\\t\\treplySubmitting = false;\\n\\t\\tif (ok) replyDraft = '';\\n\\t}\\n\\n\\tfunction remove(comment: PRReviewComment): void {\\n\\t\\tvoid actions.deleteComment(comment.id, comment.p